import math


def stream_totals(records):
    if isinstance(records, (str, bytes)):
        raise TypeError('records must be iterable')
    try:
        records = list(records)
    except TypeError as exc:
        raise TypeError('records must be iterable') from exc
    totals = {}
    for record in records:
        if not isinstance(record, tuple):
            raise TypeError('each record must be a tuple')
        if len(record) != 2:
            raise ValueError('each record must contain two fields')
        category, amount = record
        if not isinstance(category, str):
            raise TypeError('category must be a string')
        if not category:
            raise ValueError('category must not be empty')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError('amount must be numeric')
        if not math.isfinite(amount):
            raise ValueError('amount must be finite')
        totals[category] = totals.get(category, 0) + amount
    return list(totals.items())
```

